wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // Precondition (requires): len(text) <= 100000, measured in characters
        // as Python's len() does. Checked defensively: a violation traps, so no
        // output is produced and the postcondition is not engaged.
        assert!(
            reply.text.chars().count() <= 100_000,
            "requires violated: len(text) > 100000"
        );

        // The session identity and the delivery flag are the host's to report.
        // They are never fabricated here. If the host reports a failed delivery
        // or an absent session, we trap rather than return an output that would
        // break the ensures clauses.
        let confirmation = response_channel::send(&reply.text);

        assert!(
            confirmation.delivered,
            "ensures violated: delivered == false"
        );
        assert!(
            !confirmation.session.is_empty(),
            "ensures violated: session_id not present"
        );

        confirmation
    }
}

export!(Node);
